//! The built-in catalogue (`data/catalogue.json`, generated by
//! `scripts/gen-assistant-catalogue.mjs`) and command validation.

use std::collections::BTreeSet;

use serde::Deserialize;

use orkestr_protocol::methods::computer::{AssistantCommand, CommandSet, ComputerAction};

use crate::error::{ComputerError, ComputerResult};

#[derive(Deserialize)]
struct CatalogueFile {
    format: String,
    version: u32,
    sets: Vec<CommandSet>,
}

/// The embedded catalogue JSON.
pub const CATALOGUE_JSON: &str = include_str!("../data/catalogue.json");

/// Parses the built-in catalogue (every set marked `builtin`).
///
/// # Errors
/// `Invalid` when the embedded document is broken (a build bug; tested).
pub fn builtin_sets() -> ComputerResult<Vec<CommandSet>> {
    let f: CatalogueFile =
        serde_json::from_str(CATALOGUE_JSON).map_err(|e| ComputerError::Invalid(format!("catalogue: {e}")))?;
    if f.format != "orkestr-command-catalogue" || f.version != 1 {
        return Err(ComputerError::Invalid("catalogue: unknown format".into()));
    }
    let mut sets = f.sets;
    for s in &mut sets {
        s.builtin = true;
        validate_set(s)?;
    }
    Ok(sets)
}

/// `{slot}` names used in a template string.
#[must_use]
pub fn slots_in(s: &str) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    let mut rest = s;
    while let Some(i) = rest.find('{') {
        let after = &rest[i + 1..];
        let Some(j) = after.find('}') else { break };
        let name = &after[..j];
        if !name.is_empty() && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
            out.insert(name.to_owned());
        }
        rest = &after[j + 1..];
    }
    out
}

/// Slots referenced by steps.
#[must_use]
pub fn step_slots(steps: &[ComputerAction]) -> BTreeSet<String> {
    let v = serde_json::to_value(steps).unwrap_or_default();
    let mut out = BTreeSet::new();
    walk(&v, &mut out);
    out
}

fn walk(v: &serde_json::Value, out: &mut BTreeSet<String>) {
    match v {
        serde_json::Value::String(s) => out.extend(slots_in(s)),
        serde_json::Value::Array(a) => a.iter().for_each(|x| walk(x, out)),
        serde_json::Value::Object(o) => o.values().for_each(|x| walk(x, out)),
        _ => {}
    }
}

fn valid_id(id: &str) -> bool {
    (1..=96).contains(&id.len())
        && id.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, '-' | '.' | '_'))
}

/// Maximum nesting of `If` steps.
pub const MAX_DEPTH: usize = 4;
/// Maximum steps of one command (flattened).
pub const MAX_STEPS: usize = 64;

fn count_steps(steps: &[ComputerAction], depth: usize) -> ComputerResult<usize> {
    if depth > MAX_DEPTH {
        return Err(ComputerError::Invalid(format!("conditions nest deeper than {MAX_DEPTH}")));
    }
    let mut n = 0;
    for s in steps {
        n += 1;
        if let ComputerAction::If { then, otherwise, .. } = s {
            n += count_steps(then, depth + 1)? + count_steps(otherwise, depth + 1)?;
        }
    }
    Ok(n)
}

/// Validates a command: id, phrases, steps, and that every phrase provides
/// every slot the steps use.
///
/// # Errors
/// `Invalid` with the reason.
pub fn validate_command(c: &AssistantCommand) -> ComputerResult<()> {
    if !valid_id(&c.id) {
        return Err(ComputerError::Invalid(format!("bad command id `{}`", c.id)));
    }
    if c.phrases.is_empty() || c.phrases.iter().any(|p| p.trim().is_empty() || p.len() > 300) {
        return Err(ComputerError::Invalid(format!("{}: needs 1+ non-empty phrases (≤ 300 chars)", c.id)));
    }
    if c.steps.is_empty() {
        return Err(ComputerError::Invalid(format!("{}: needs at least one step", c.id)));
    }
    let n = count_steps(&c.steps, 0)?;
    if n > MAX_STEPS {
        return Err(ComputerError::Invalid(format!("{}: {n} steps (max {MAX_STEPS})", c.id)));
    }
    let used = step_slots(&c.steps);
    for p in &c.phrases {
        let have = slots_in(p);
        if let Some(missing) = used.iter().find(|s| !have.contains(*s)) {
            return Err(ComputerError::Invalid(format!("{}: phrase “{p}” lacks the slot {{{missing}}}", c.id)));
        }
    }
    Ok(())
}

/// Validates a whole set (unique command ids).
///
/// # Errors
/// `Invalid` with the reason.
pub fn validate_set(s: &CommandSet) -> ComputerResult<()> {
    if !valid_id(&s.id) || s.id.len() > 64 {
        return Err(ComputerError::Invalid(format!("bad set id `{}`", s.id)));
    }
    if s.name.trim().is_empty() {
        return Err(ComputerError::Invalid(format!("set {} needs a name", s.id)));
    }
    if s.commands.len() > 5000 {
        return Err(ComputerError::Invalid("too many commands in one set (max 5000)".into()));
    }
    let mut ids = BTreeSet::new();
    for c in &s.commands {
        validate_command(c)?;
        if !ids.insert(c.id.as_str()) {
            return Err(ComputerError::Invalid(format!("duplicate command id `{}` in set {}", c.id, s.id)));
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn catalogue_has_at_least_1000_unique_valid_commands() {
        let sets = builtin_sets().expect("catalogue parses");
        let mut ids = HashSet::new();
        let mut phrases = 0;
        for s in &sets {
            assert!(s.builtin);
            for c in &s.commands {
                assert!(ids.insert(c.id.clone()), "duplicate id {}", c.id);
                phrases += c.phrases.len();
                // every command round-trips through the wire format
                let v = serde_json::to_value(c).unwrap();
                let back: AssistantCommand = serde_json::from_value(v).unwrap();
                assert_eq!(&back, c);
            }
        }
        assert!(ids.len() >= 1000, "only {} commands", ids.len());
        assert!(phrases >= 5000, "only {phrases} phrases");
        let cats: HashSet<&str> = sets.iter().flat_map(|s| s.commands.iter().map(|c| c.category.as_str())).collect();
        for c in ["apps", "windows", "keys", "scroll", "media", "system", "settings", "web", "files", "typing"] {
            assert!(cats.contains(c), "category {c} missing");
        }
    }

    #[test]
    fn both_languages_are_covered() {
        let sets = builtin_sets().unwrap();
        let all: Vec<&AssistantCommand> = sets.iter().flat_map(|s| s.commands.iter()).collect();
        let cyr = |p: &str| p.chars().any(|c| ('\u{0400}'..='\u{04FF}').contains(&c));
        let both = all.iter().filter(|c| c.phrases.iter().any(|p| cyr(p)) && c.phrases.iter().any(|p| !cyr(p))).count();
        assert!(both * 100 / all.len() >= 95, "{both}/{} commands have ru + en phrases", all.len());
        assert!(all.iter().all(|c| !c.title.en.is_empty() && !c.title.ru.is_empty()));
    }

    #[test]
    fn slots_must_be_provided_by_every_phrase() {
        let mut c: AssistantCommand = serde_json::from_value(serde_json::json!({
            "id": "x", "phrases": ["open {app}", "open it"], "steps": [{"type": "Launch", "target": "{app}"}]
        }))
        .unwrap();
        assert!(validate_command(&c).is_err());
        c.phrases.pop();
        assert!(validate_command(&c).is_ok());
        assert_eq!(slots_in("a {x} b {y_1} {}"), ["x", "y_1"].iter().map(|s| (*s).to_owned()).collect());
    }
}
